/**
 * host list -> nginx/conf.d/10-app.conf (SDS §2.3, §3, §12.3 as amended by E-5/E-12).
 *
 * The generated file is the only place a tenant is spelled into nginx config:
 *   - a `map $host $tenant` so one limit_req_zone can be keyed per tenant
 *   - one server block per tenant, listing every host of that tenant
 *   - a demos vhost with the single path-prefix location (no per-demo block)
 *   - an admin vhost that proxies to the same app, and nothing else
 *
 * Three properties are structural, not cosmetic (E-5):
 *   - every `location` regex is QUOTED: nginx's tokenizer reads an unquoted `{`
 *     as a block delimiter, so `{0,39}` in a bare regex fails to load at all;
 *   - the demo key grammar is `[a-z0-9][a-z0-9-]{0,39}` — the same 40-character
 *     maximum as `control.db`'s `tenant.key` CHECK, so every key the control
 *     plane accepts is reachable through `/demo/`;
 *   - `listen 80` is on every block (§12.5 promises a host serves on 80 while its
 *     certificate is `pending`) and `listen 443 ssl` is emitted only for a host
 *     whose `domain.cert_state = 'issued'`, because a block that listens on 443
 *     without a certificate fails `nginx -t`.
 *
 * `X-Skunkworks-Tenant ""` and `X-Forwarded-Prefix ""` live in
 * snippets/skunk-proxy.conf, not here: the snippet is the one include inside
 * every proxy_pass location.
 */
import Database from 'better-sqlite3';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { parseAdminAllowlist, parseAdminAllowlistFrom } from '../app/admin/allowlist.ts';
import { adminHostOf, demosHostOf } from '../app/env.ts';

export interface GenOptions {
  edgePlaceholder?: string;
  adminHost: string;
  demosHost: string;
  boxRps?: number;
  /**
   * §9.1a (E-17): the parsed blocks. `[]` (the exported-bundle value) emits no
   * access directive at all — never an accidental `deny all`.
   */
  adminAllowlist?: readonly string[];
}

interface HostRow {
  host: string;
  key: string;
  cert_state?: string;
}

/** §12.3: rate = min(20r/s, floor(SKW_BOX_RPS / hot_tenants)), burst = 2 x rate. */
export function tenantRate(boxRps: number, hotTenants: number): { rate: number; burst: number } {
  const hot = Math.max(1, hotTenants);
  const rate = Math.min(20, Math.max(1, Math.floor(boxRps / hot)));
  return { rate, burst: rate * 2 };
}

/** The demo key grammar, quoted at the call site (§12.3, E-5). */
export const DEMO_KEY = '[a-z0-9][a-z0-9-]{0,39}';

export function generateAppConf(rows: readonly HostRow[], opts: GenOptions): string {
  if (rows.length === 0) throw new Error('nginx_gen: no hosts in control.db.domain');
  // The demos and admin vhosts are emitted by name. A domain row for either
  // name would emit a second server block with the same server_name, and nginx
  // keeps the first and warns — which silently disables the /demo/ rewrite or
  // shadows the admin surface (§9.1 rule 3, E-2).
  for (const reserved of [opts.demosHost, opts.adminHost]) {
    const clash = rows.find((r) => r.host === reserved);
    if (clash !== undefined) {
      throw new Error(
        `nginx_gen: ${reserved} is the ${reserved === opts.demosHost ? 'demos' : 'admin'} vhost and cannot also be a domain of tenant ${clash.key}`,
      );
    }
  }
  const { rate, burst } = tenantRate(opts.boxRps ?? 192, new Set(rows.map((r) => r.key)).size);

  const byTenant = new Map<string, string[]>();
  const issued = new Set<string>();
  for (const r of [...rows].sort((a, b) => (a.key === b.key ? a.host.localeCompare(b.host) : a.key.localeCompare(b.key)))) {
    const list = byTenant.get(r.key) ?? [];
    list.push(r.host);
    byTenant.set(r.key, list);
    if (r.cert_state === 'issued') issued.add(r.key);
  }

  const out: string[] = [];
  out.push('# GENERATED by tools/nginx_gen.ts from control.db — do not edit by hand.');
  out.push('# Regenerate: node dist/tools/nginx_gen.js --data-dir /srv/data --out /etc/nginx/conf.d/10-app.conf');
  out.push('');
  out.push('# one tenant per $tenant bucket (§12.3: derived from SKW_BOX_RPS and hot tenants)');
  // D18 / §7.1: a renamed key 301s at the edge. `map` is http-scope only, so the block lives
  // here and the farm (`app/assets/farm.ts`) writes the entries into an include *inside* it —
  // which is also why a fresh box starts: the variable is declared by this block even when
  // the glob matches no file (nginx tolerates an unmatched include mask).
  out.push('# §7.1: a renamed key 301s at the edge; the entries are generated by app/assets/farm.ts.');
  out.push('map $uri $skw_media_alias {');
  out.push('    default "";');
  out.push('    include /srv/content/edge/*.inc;');
  out.push('}');
  out.push('');
  out.push('map $host $tenant {');
  out.push('    hostnames;');
  out.push('    default "";');
  for (const [key, hosts] of byTenant) {
    for (const host of hosts) out.push(`    ${host} ${key};`);
  }
  out.push('}');
  out.push('');
  out.push(`limit_req_zone $tenant zone=tenant:10m rate=${rate}r/s;`);
  out.push('');

  for (const [key, hosts] of byTenant) {
    out.push(`# tenant ${key}`);
    out.push('server {');
    // 80 always; 443 only when the certificate exists (§12.5, E-5).
    out.push(issued.has(key) ? '    listen 80; listen 443 ssl;' : '    listen 80;');
    out.push(`    server_name ${hosts.join(' ')};`);
    out.push('');
    out.push('    location / {');
    out.push(`        limit_req zone=tenant burst=${burst} nodelay;`);
    out.push('        include /etc/nginx/snippets/skunk-proxy.conf;');
    out.push('        proxy_pass http://app:3000;');
    out.push('    }');
    out.push('');
    out.push('    location /media/ {');
    // D18 / §7.1: a renamed key 301s here, from a `map` the farm generates. `return` inside
    // `if` is one of the two uses of `if` nginx documents as safe, and it runs before the
    // alias lookup — so an old key never depends on a link still existing. An empty map (no
    // renames, or no map file at all) makes the condition false and the request falls
    // through to `try_files`, which is the 404 path a missing key takes.
    out.push('        if ($skw_media_alias) { return 301 $skw_media_alias; }');
    out.push('        alias /srv/content/public/;');
    out.push('        try_files $uri =404;');
    out.push('        add_header Cache-Control "public, max-age=31536000, immutable";');
    out.push('    }');
    out.push('');
    // §7.5 (S3d): the stamped per-purchaser renders. A **second** internal location, with
    // its own tree, so `content/media/` keeps exactly one meaning: the immutable store
    // blob that every buyer shares. A gated asset's hand-off is this one, never the other.
    // `alias` is the directory, so the URI carries `wm/<spec_sha>/<asset_sha>.<ext>`.
    out.push('    location /__protected/wm/ {');
    out.push('        internal;');
    out.push('        alias /srv/content/protected/wm/;');
    out.push('        limit_rate 1m;');
    out.push('    }');
    out.push('');
    out.push('    location /__protected/ {');
    out.push('        internal;');
    out.push('        alias /srv/content/media/;');
    out.push('        limit_rate 1m;');
    out.push('    }');
    out.push('}');
    out.push('');
  }

  out.push('# demos: the only host that serves /demo/ (C-25). No per-demo server block.');
  out.push('server {');
  out.push('    listen 80; listen 443 ssl;');
  out.push(`    server_name ${opts.demosHost};`);
  out.push('');
  out.push('    # The slash-less form FIRST. If the proxying location below is the only one, it');
  out.push('    # matches /demo/<key> with an empty suffix, the rewrite does not fire, and an');
  out.push('    # unstripped path reaches the app, which is forbidden to strip it (C-2) and 404s.');
  out.push(`    location ~ "^/demo/(?<demo_key>${DEMO_KEY})$" {`);
  out.push('        return 301 /demo/$demo_key/$is_args$args;');
  out.push('    }');
  out.push('');
  out.push(`    location ~ "^/demo/(?<demo_key>${DEMO_KEY})(/.*)$" {`);
  out.push(`        rewrite "^/demo/${DEMO_KEY}/(.*)$" /$1 break;`);
  out.push('        include /etc/nginx/snippets/skunk-proxy.conf;');
  out.push('        proxy_set_header X-Skunkworks-Tenant $demo_key;');
  out.push('        proxy_set_header X-Forwarded-Prefix "/demo/$demo_key";');
  out.push('        proxy_pass http://app:3000;');
  out.push('    }');
  out.push('');
  out.push('    location / { return 404; }');
  out.push('}');
  out.push('');
  out.push('# admin: the only host that serves /admin (E-2, §9.1). No /demo/, no /media/.');
  out.push('server {');
  out.push('    listen 80; listen 443 ssl;');
  out.push(`    server_name ${opts.adminHost};`);
  out.push('');
  const allowlist = opts.adminAllowlist ?? [];
  if (allowlist.length > 0) {
    // E-17: one `allow` per SKW_ADMIN_ALLOWLIST block, then `deny all;`, in the
    // admin block and in no other. With an empty list these lines are absent, so
    // the default is the app's own authentication and never an accidental deny.
    out.push('    # SKW_ADMIN_ALLOWLIST (§9.1a) — the edge admits these peers and refuses every other.');
    for (const block of allowlist) out.push(`    allow ${block};`);
    out.push('    deny  all;');
    out.push('');
  }
  out.push('    location / {');
  out.push('        include /etc/nginx/snippets/skunk-proxy.conf;');
  out.push('        proxy_pass http://app:3000;');
  out.push('    }');
  out.push('}');
  out.push('');
  return out.join('\n');
}

export function readHosts(controlDbPath: string): HostRow[] {
  const db = new Database(controlDbPath, { readonly: true, fileMustExist: true });
  try {
    return db
      .prepare(
        `SELECT d.host AS host, t.key AS key, d.cert_state AS cert_state
           FROM domain d JOIN tenant t ON t.id = d.tenant_id
          ORDER BY t.key, d.host`,
      )
      .all() as HostRow[];
  } finally {
    db.close();
  }
}

/**
 * E-17: the edge's one answer to "is this value usable" — the shared parser,
 * unchanged. Kept as a named function so a test can assert the message is
 * byte-identical to the app's, rather than inferring it from `main()`.
 */
export function parseAllowlistForGenerator(raw: string | undefined): string[] {
  return parseAdminAllowlist(raw);
}

export function main(argv: readonly string[] = process.argv.slice(2)): number {
  let dataDir = process.env.SKW_DATA_DIR ?? '/srv/data';
  let out = join(process.cwd(), 'nginx', 'conf.d', '10-app.conf');
  let boxRps = Number(process.env.SKW_BOX_RPS ?? '192');
  // E-17: SKW_ADMIN_HOST and SKW_DEMOS_HOST are deleted. The admin host is the
  // host component of SKW_ADMIN_ORIGIN (§9.1) and demos is derived from it; the
  // two flags below stay as test-only overrides.
  const derivedAdmin = adminHostOf(process.env.SKW_ADMIN_ORIGIN ?? '');
  if (derivedAdmin === null) {
    throw new Error('nginx_gen: SKW_ADMIN_ORIGIN is required — the admin host is derived from it (E-17, §9.1a)');
  }
  let adminHost = derivedAdmin;
  let demosHost = demosHostOf(derivedAdmin);
  let adminAllowlist = parseAdminAllowlistFrom(process.env);
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--data-dir') dataDir = argv[i + 1] ?? dataDir;
    else if (arg === '--out') out = argv[i + 1] ?? out;
    else if (arg === '--admin-host') adminHost = argv[i + 1] ?? adminHost;
    else if (arg === '--demos-host') demosHost = argv[i + 1] ?? demosHost;
    else if (arg === '--box-rps') boxRps = Number(argv[i + 1] ?? boxRps);
  }
  const text = generateAppConf(readHosts(join(dataDir, 'control.db')), { adminHost, demosHost, boxRps, adminAllowlist });
  writeFileSync(out, text);
  process.stdout.write(`wrote ${out} (${text.split('\n').length} lines)\n`);
  return 0;
}

function isMain(metaUrl: string): boolean {
  const entry = process.argv[1];
  if (entry === undefined) return false;
  return new URL(metaUrl).pathname === entry;
}

if (isMain(import.meta.url)) {
  process.exitCode = main();
}
